#!/usr/bin/env bash
# Assemble the independent-machine-network (order 2026-10-23 (independent machine network)) delivery directory with an explicit allowlist. Never copies keys,
# credentials, live databases, model weights, private prompts/documents, vectors, node identities, wallets, venvs or environment files.
set -u
DELIVER="$1"; A="$2"; BASE="$(cat "$A/BASE_REVISION.txt")"; HEAD="${METACOIN_PACKAGE_REVISION:-$(git rev-parse HEAD)}"; NAME=metacoin-independent-machine-network   # METACOIN_PACKAGE_REVISION pins the SOURCE candidate when records commits (work/ only) sit above it
mkdir -p "$DELIVER/test-logs" "$DELIVER/clean-export-logs" "$DELIVER/journeys" "$DELIVER/benchmarks" "$DELIVER/browser-screenshots" "$DELIVER/examples" "$DELIVER/docs" "$DELIVER/spec" "$DELIVER/vectors" "$DELIVER/conformance" "$DELIVER/provider_client" "$DELIVER/demonstration" "$DELIVER/protocol-data" "$DELIVER/lunar-data"
git diff "$BASE" "$HEAD" -- . ':!work' > "$DELIVER/$NAME-session-vs-${BASE:0:7}.patch"
git log --format='%H %s' "$BASE..$HEAD" > "$DELIVER/commits.txt"
echo "$HEAD" > "$DELIVER/SOURCE_REVISION.txt"; echo "$BASE" > "$DELIVER/BASE_REVISION.txt"
[ -f "$DELIVER/$NAME-source.zip" ] || { TMPX="$(mktemp -d)"; git archive --format=tar --prefix=$NAME/ "$HEAD" | tar -x -C "$TMPX" && rm -rf "$TMPX/$NAME/work" && (cd "$TMPX" && zip -qr "$DELIVER/$NAME-source.zip" $NAME) && rm -rf "$TMPX"; }
git ls-files | grep -v '^work/' > "$DELIVER/SOURCE_ALLOWLIST.txt"
cp metacoin_service/requirements.lock "$DELIVER/requirements-service.lock"; cp metacoin_service/requirements-compute.txt "$DELIVER/requirements-compute.txt"; cp metacoin_service/README.md "$DELIVER/SERVICE_README.md"
cp metacoin_service/native/checker.py "$DELIVER/native_checker.py"; cp metacoin_service/native/vectors.py "$DELIVER/native_vectors.py"; cp metacoin_service/native/protocol.py "$DELIVER/native_protocol.py"; cp metacoin_service/native/planner.py "$DELIVER/native_planner.py"; cp metacoin_service/native/model_network.py "$DELIVER/native_model_network.py"; cp metacoin_service/native/pools.py "$DELIVER/native_pools.py"; cp metacoin_service/native/hostconfig.py "$DELIVER/native_hostconfig.py"
cp -r provider_client/metacoin_provider provider_client/pyproject.toml provider_client/README.md "$DELIVER/provider_client/"; find "$DELIVER/provider_client" -name __pycache__ -type d -exec rm -rf {} + 2>/dev/null
cp provider_client/metacoin_provider/conformance/v1/fixtures.json "$DELIVER/conformance/provider-conformance-v2.json"
cp docs/native/*.md docs/native/*.json "$DELIVER/docs/" 2>/dev/null; cp docs/native/PROTOCOL.md docs/native/protocol-spec.json "$DELIVER/spec/"
cp metacoin_service/lunar/data/* "$DELIVER/lunar-data/"
PYTHONPATH=. .venv-service/bin/python -m metacoin_service.native.vectors > "$DELIVER/vectors/vector-results.json" 2>/dev/null; PYTHONPATH=. .venv-service/bin/python -c "import json; from metacoin_service.native import vectors; print(json.dumps(vectors.generate(), indent=1))" > "$DELIVER/vectors/vectors.json" 2>/dev/null
cp metacoin_service/examples/work_client.py "$DELIVER/examples/work_client_example.py"; cp "$A"/examples/* "$DELIVER/examples/" 2>/dev/null
cp protocol/ledger_data.jsonl "$DELIVER/protocol-data/ledger_data.jsonl"; cp mission_verdict.json "$DELIVER/protocol-data/mission_verdict.json"; sha256sum protocol/ledger_data.jsonl mission_verdict.json > "$DELIVER/protocol-data/SHA256SUMS.txt"
printf '%s\n' "Runtime data outside the git archive (gitignored in the public repo by design):" "  protocol-data/ledger_data.jsonl   -> <repo>/protocol/ledger_data.jsonl" "  protocol-data/mission_verdict.json -> <repo>/mission_verdict.json" "Copy them to those paths before running the service, the journeys or the demonstration from the archive." > "$DELIVER/protocol-data/README.txt"
cp work/independent-machine-network-session/SESSION_STATE.md "$DELIVER/"; cp work/independent-machine-network-session/clean_export.sh work/independent-machine-network-session/package.sh work/independent-machine-network-session/run_benchmark.py work/independent-machine-network-session/finalize.sh work/independent-machine-network-session/candidate_build.py work/independent-machine-network-session/ledger_build.py work/independent-machine-network-session/report_build.py work/independent-machine-network-session/unit_summary.py "$DELIVER/" 2>/dev/null; cp "$A"/benchmarks/*.log "$DELIVER/benchmarks/" 2>/dev/null; mkdir -p "$DELIVER/benchmarks/at-2ff4da5" && cp "$A"/benchmarks/at-2ff4da5/*.json "$DELIVER/benchmarks/at-2ff4da5/" 2>/dev/null
cp "$A"/logs/*.log "$A"/logs/*.txt "$DELIVER/test-logs/" 2>/dev/null; cp "$A"/journeys/*.json "$DELIVER/journeys/" 2>/dev/null; cp "$A"/benchmarks/*.json "$DELIVER/benchmarks/" 2>/dev/null; cp "$A"/clean-export/* "$DELIVER/clean-export-logs/" 2>/dev/null; cp "$A"/shots/* "$DELIVER/browser-screenshots/" 2>/dev/null; cp "$A"/demonstration/* "$DELIVER/demonstration/" 2>/dev/null; cp -r "$A"/hostconfig-sample "$DELIVER/examples/hostconfig-sample" 2>/dev/null; cp "$A"/examples/* "$DELIVER/examples/" 2>/dev/null
for f in FEATURE_LEDGER.json IMPLEMENTATION_INDEX.md MIGRATIONS.json TRUST_MODEL.md HANDOFF.md MIGRATION_NOTES.md CLEAN_START.md IMPLEMENTATION_REPORT.md DELIVERY_INDEX.md ISSUES.md CANDIDATE.json live-untouched.json verification-results.json openapi.json mcp-schema.json BASELINE_POINTERS.txt BASE_REVISION.txt RECORDS_COMMIT.txt bpv7-probe.json EXTERNAL_TRACKS.md model-network-report.json hostconfig-sample.json; do [ -f "$A/$f" ] && cp "$A/$f" "$DELIVER/"; done
echo "== scans ($(date -u +%Y-%m-%dT%H:%M:%SZ)) archive $HEAD base $BASE" > "$DELIVER/DELIVERY_SCANS.txt"
{ unzip -Z1 "$DELIVER/$NAME-source.zip" | grep -iE "\.age$|\.ed25519|bootstrap\.json|sqlite|\.venv|\.env$|/work/|node-.*\.json$|\.safetensors|\.npy$|\.onnx$|artifacts/[0-9a-f]{32}" && echo "PRIVATE/UNWANTED MATERIAL IN ARCHIVE"; } || echo "archive allowlist ok: no keys, credentials, databases, weights, vectors, node identities, venv or work dir" >> "$DELIVER/DELIVERY_SCANS.txt"
{ grep -rlE "mck_[A-Za-z0-9_-]{20}|mcn_[A-Za-z0-9_-]{20}" "$DELIVER" --include='*.json' --include='*.log' --include='*.txt' --include='*.patch' --include='*.md' | grep -v -E "openapi|capabilities" && echo "TOKEN-LIKE STRING FOUND"; } || echo "no bearer/node-credential-shaped strings in logs/results" >> "$DELIVER/DELIVERY_SCANS.txt"
{ grep -rl "AGE-SECRET-KEY\|BEGIN PRIVATE KEY\|private_key_hex" "$DELIVER" | grep -v -E "\.patch$|SERVICE_README|openapi|source\.zip|package\.sh$|DELIVERY_SCANS|native_hostconfig\.py$" && echo "SECRET MATERIAL FOUND"; } || echo "no secret key material outside source text" >> "$DELIVER/DELIVERY_SCANS.txt"
unzip -tq "$DELIVER/$NAME-source.zip" >> "$DELIVER/DELIVERY_SCANS.txt" 2>&1
(cd "$DELIVER" && find . -type f ! -name SHA256SUMS -print0 | sort -z | xargs -0 sha256sum > SHA256SUMS && sha256sum -c --quiet SHA256SUMS && echo "manifest ok: $(wc -l < SHA256SUMS) files")
cat "$DELIVER/DELIVERY_SCANS.txt"; du -sh "$DELIVER"
